script:
let current_request_type_name = null;


/* =====================================================
   Card Request
   ===================================================== */

frappe.ui.form.on("Card Request", {

    /* =================================================
       Refresh
       ================================================= */

    refresh(frm) {

        load_request_type_name(frm);

        control_employee_photo(frm);

        show_photo_status(frm);

        update_photo_action_message(frm);
    },


    /* =================================================
       عند تغيير نوع الطلب
       ================================================= */

    request_type(frm) {

        current_request_type_name = null;

        clear_reason_style(frm);

        load_request_type_name(frm);
    },


    /* =================================================
       عند اختيار الموظف
       ================================================= */

    employee(frm) {

        /*
         * عند تغيير الموظف:
         * نحمل صورته من Employee
         */

        load_employee_photo(frm);

        control_employee_photo(frm);
    },


    /* =================================================
       عند تغيير السبب
       ================================================= */

    reason(frm) {

        clear_reason_style(frm);
    },


    /* =================================================
       عند تغيير صورة الموظف
       ================================================= */

    employee_photo(frm) {

        /*
         * إذا قام مختص تقنية المعلومات برفع صورة جديدة
         * فإنها تصبح قيد المراجعة تلقائيًا.
         */

        if (frm.doc.employee_photo) {

            /*
             * لا نغير الحالة إذا كانت الصورة
             * معتمدة بالفعل.
             */

            if (frm.doc.photo_status !== "معتمدة") {

                frm.set_value(
                    "photo_status",
                    "قيد المراجعة"
                );
            }

        } else {

            /*
             * إذا تم حذف الصورة
             */

            frm.set_value(
                "photo_status",
                "مطلوبة"
            );
        }

        show_photo_status(frm);

        update_photo_action_message(frm);
    },


    /* =================================================
       عند تغيير حالة الصورة
       ================================================= */

    photo_status(frm) {

        show_photo_status(frm);

        update_photo_action_message(frm);
    },


    /* =================================================
       التحقق قبل الحفظ
       ================================================= */

    validate(frm) {

        const types_with_reason = [
            "بدل فاقد",
            "تجديد",
            "تعديل بيانات",
            "إلغاء"
        ];


        if (
            types_with_reason.includes(
                current_request_type_name
            )
        ) {

            if (!frm.doc.reason) {

                show_reason_style(frm);

            } else {

                clear_reason_style(frm);
            }
        }
    },


    /* =================================================
       قبل تنفيذ Workflow Action
       ================================================= */

    before_workflow_action(frm) {

        const action =
            frm.selected_workflow_action;


        console.log(
            "=== CARD REQUEST WORKFLOW ==="
        );


        console.log(
            "Workflow Action:",
            action
        );


        /*
         * =================================================
         * مهم جدًا
         * =================================================
         *
         * لا نستخدم frappe.throw() هنا.
         *
         * ولا نستدعي receive_card_request().
         *
         * ولا ننشئ Employee Identity Card.
         *
         * ولا ننفذ عملية تجهيز البطاقة يدويًا.
         *
         * التحقق النهائي يتم من Python:
         *
         * CardRequest.before_workflow_action()
         *                  ↓
         * EmployeeCardService.validate_request_before_print()
         *
         * هذا يمنع تعارض Client Script مع Workflow.
         *
         * =================================================
         */


        /* =============================================
           تجهيز البطاقة
           ============================================= */

        if (
            action === "تجهيز البطاقة"
        ) {

            console.log(
                "→ إجراء تجهيز البطاقة"
            );

            console.log(
                "→ التحقق سيتم من Python"
            );

            /*
             * لا يوجد frappe.throw()
             *
             * السماح للـ Workflow بالاستمرار.
             */

            return;
        }


        /* =============================================
           طباعة البطاقة
           ============================================= */

        if (
            action === "طباعة البطاقة"
        ) {

            console.log(
                "→ إجراء طباعة البطاقة"
            );

            console.log(
                "→ التحقق سيتم من Python"
            );

            /*
             * السماح للـ Workflow بالاستمرار.
             */

            return;
        }


        /* =============================================
           أي إجراء Workflow آخر
           ============================================= */

        console.log(
            "→ Workflow Action آخر:",
            action
        );

        return;
    },


    /* =================================================
       تغير Workflow State
       ================================================= */

    workflow_state(frm) {

        control_employee_photo(frm);

        show_photo_status(frm);

        update_photo_action_message(frm);
    }

});


/* =====================================================
   معرفة اسم نوع الطلب
   ===================================================== */

function load_request_type_name(frm) {

    if (!frm.doc.request_type) {

        current_request_type_name = null;

        frm.set_df_property(
            "reason",
            "hidden",
            1
        );

        frm.refresh_field(
            "reason"
        );

        return;
    }


    frappe.db.get_value(
        "Card Request Type",
        frm.doc.request_type,
        "request_type_name"
    ).then(r => {

        current_request_type_name =
            r.message?.request_type_name || null;


        const needs_reason = [
            "بدل فاقد",
            "تجديد",
            "تعديل بيانات",
            "إلغاء"
        ].includes(
            current_request_type_name
        );


        frm.set_df_property(
            "reason",
            "hidden",
            needs_reason ? 0 : 1
        );


        frm.refresh_field(
            "reason"
        );

    });
}


/* =====================================================
   تحميل صورة الموظف
   ===================================================== */

function load_employee_photo(frm) {

    if (!frm.doc.employee) {

        frm.set_value(
            "employee_photo",
            ""
        );

        frm.set_value(
            "photo_status",
            "مطلوبة"
        );

        show_photo_status(frm);

        update_photo_action_message(frm);

        return;
    }


    frappe.db.get_value(
        "Employee",
        frm.doc.employee,
        [
            "employee_name",
            "image"
        ]
    ).then(r => {

        const data =
            r.message || {};


        /* =============================================
           توجد صورة
           ============================================= */

        if (data.image) {

            frm.set_value(
                "employee_photo",
                data.image
            );


            /*
             * إذا كانت الصورة ليست معتمدة
             * نجعلها قيد المراجعة.
             */

            if (
                frm.doc.photo_status !==
                "معتمدة"
            ) {

                frm.set_value(
                    "photo_status",
                    "قيد المراجعة"
                );
            }


            frm.refresh_field(
                "employee_photo"
            );

            frm.refresh_field(
                "photo_status"
            );


            show_photo_status(frm);

            update_photo_action_message(frm);


            frappe.show_alert({

                message:
                    "تم تحميل صورة الموظف من ملف الموظف.",

                indicator:
                    "green"

            });


            return;
        }


        /* =============================================
           لا توجد صورة
           ============================================= */

        frm.set_value(
            "employee_photo",
            ""
        );


        frm.set_value(
            "photo_status",
            "مطلوبة"
        );


        frm.refresh_field(
            "employee_photo"
        );

        frm.refresh_field(
            "photo_status"
        );


        show_photo_status(frm);

        update_photo_action_message(frm);


        frappe.show_alert({

            message:
                "لا توجد صورة للموظف. يمكن لمختص تقنية المعلومات إرفاق الصورة.",

            indicator:
                "orange"

        });

    }).catch(error => {

        console.error(
            "خطأ أثناء تحميل صورة الموظف:",
            error
        );

    });
}


/* =====================================================
   حالة الصورة
   ===================================================== */

function show_photo_status(frm) {

    const field =
        frm.get_field(
            "employee_photo"
        );


    if (!field) {
        return;
    }


    const wrapper =
        field.$wrapper;


    wrapper
        .find(
            ".employee-photo-status"
        )
        .remove();


    let message = "";

    let indicator = "";


    /* =============================================
       لا توجد صورة
       ============================================= */

    if (
        !frm.doc.employee_photo
    ) {

        message =
            "⚠ لا توجد صورة — مطلوب إرفاق صورة الموظف.";

        indicator =
            "#dc3545";
    }


    /* =============================================
       الصورة معتمدة
       ============================================= */

    else if (
        frm.doc.photo_status ===
        "معتمدة"
    ) {

        message =
            "✓ صورة الموظف معتمدة.";

        indicator =
            "#198754";
    }


    /* =============================================
       الصورة قيد المراجعة
       ============================================= */

    else if (
        frm.doc.photo_status ===
        "قيد المراجعة"
    ) {

        message =
            "⚠ توجد صورة — بانتظار الاعتماد.";

        indicator =
            "#f39c12";
    }


    /* =============================================
       الصورة مرفوضة
       ============================================= */

    else if (
        frm.doc.photo_status ===
        "مرفوضة"
    ) {

        message =
            "✕ صورة الموظف مرفوضة — يرجى رفع صورة جديدة.";

        indicator =
            "#dc3545";
    }


    /* =============================================
       حالة أخرى
       ============================================= */

    else {

        message =
            "✓ توجد صورة للموظف.";

        indicator =
            "#198754";
    }


    wrapper.append(`

        <div
            class="employee-photo-status"
            style="
                margin-top:6px;
                font-size:13px;
                font-weight:600;
                color:${indicator};
            "
        >
            ${message}
        </div>

    `);
}


/* =====================================================
   رسالة إرشادية أسفل حالة الصورة
   ===================================================== */

function update_photo_action_message(frm) {

    const field =
        frm.get_field(
            "photo_status"
        );


    if (!field) {
        return;
    }


    const wrapper =
        field.$wrapper;


    wrapper
        .find(
            ".photo-action-message"
        )
        .remove();


    const is_it_user =
        frappe.user.has_role(
            "IT Card Officer"
        );


    const state =
        frm.doc.workflow_state;


    /*
     * يسمح بالتعديل فقط لمختص تقنية المعلومات
     * أثناء Card Preparation.
     */

    if (
        !is_it_user ||
        state !== "Card Preparation"
    ) {

        return;
    }


    let message = "";


    /* =============================================
       لا توجد صورة
       ============================================= */

    if (
        !frm.doc.employee_photo
    ) {

        message =
            "يمكنك الآن إرفاق صورة الموظف، ثم اختيار «معتمدة» بعد التأكد منها.";
    }


    /* =============================================
       صورة قيد المراجعة
       ============================================= */

    else if (
        frm.doc.photo_status ===
        "قيد المراجعة"
    ) {

        message =
            "يرجى مراجعة الصورة، ثم تغيير حالة الصورة إلى «معتمدة» قبل تجهيز البطاقة.";
    }


    /* =============================================
       صورة مرفوضة
       ============================================= */

    else if (
        frm.doc.photo_status ===
        "مرفوضة"
    ) {

        message =
            "يرجى إرفاق صورة جديدة ثم اعتمادها.";
    }


    /* =============================================
       صورة معتمدة
       ============================================= */

    else if (
        frm.doc.photo_status ===
        "معتمدة"
    ) {

        message =
            "✓ الصورة معتمدة ويمكن الانتقال إلى تجهيز البطاقة.";
    }


    if (!message) {
        return;
    }


    wrapper.append(`

        <div
            class="photo-action-message"
            style="
                margin-top:6px;
                padding:7px 10px;
                border-radius:6px;
                background:#f8f9fa;
                color:#495057;
                font-size:12px;
                line-height:1.7;
            "
        >
            ${message}
        </div>

    `);
}


/* =====================================================
   إظهار التصميم الأحمر لحقل السبب
   ===================================================== */

function show_reason_style(frm) {

    const field =
        frm.get_field(
            "reason"
        );


    if (!field) {
        return;
    }


    frm.set_df_property(
        "reason",
        "hidden",
        0
    );


    frm.refresh_field(
        "reason"
    );


    clear_reason_style(frm);


    const wrapper =
        field.$wrapper;


    wrapper
        .find(
            ".control-input"
        )
        .css({

            "border":
                "1px solid #dc3545",

            "box-shadow":
                "0 0 0 2px rgba(220,53,69,0.12)"

        });


    wrapper
        .find(
            "textarea"
        )
        .css({

            "background-color":
                "#fff8f8"

        });


    if (
        !wrapper.find(
            ".reason-validation-message"
        ).length
    ) {

        wrapper.append(`

            <div
                class="reason-validation-message"
                style="
                    color:#dc3545;
                    font-size:13px;
                    font-weight:600;
                    margin-top:6px;
                "
            >
                ⚠ يرجى إدخال سبب الطلب
            </div>

        `);
    }
}


/* =====================================================
   إزالة التصميم الأحمر
   ===================================================== */

function clear_reason_style(frm) {

    const field =
        frm.get_field(
            "reason"
        );


    if (!field) {
        return;
    }


    const wrapper =
        field.$wrapper;


    wrapper
        .find(
            ".control-input"
        )
        .css({

            "border": "",

            "box-shadow": ""

        });


    wrapper
        .find(
            "textarea"
        )
        .css({

            "background-color": ""

        });


    wrapper
        .find(
            ".reason-validation-message"
        )
        .remove();
}


/* =====================================================
   التحكم في حقل صورة الموظف
   ===================================================== */

function control_employee_photo(frm) {

    const state =
        frm.doc.workflow_state;


    const is_it_user =
        frappe.user.has_role(
            "IT Card Officer"
        );


    /*
     * يسمح بالتعديل فقط:
     *
     * المستخدم = IT Card Officer
     *
     * والحالة = Card Preparation
     */

    const can_edit =
        is_it_user &&
        state === "Card Preparation";


    /* =============================================
       صورة الموظف
       ============================================= */

    frm.set_df_property(
        "employee_photo",
        "hidden",
        0
    );


    frm.set_df_property(
        "employee_photo",
        "read_only",
        can_edit ? 0 : 1
    );


    /* =============================================
       حالة الصورة
       ============================================= */

    frm.set_df_property(
        "photo_status",
        "hidden",
        0
    );


    frm.set_df_property(
        "photo_status",
        "read_only",
        can_edit ? 0 : 1
    );


    frm.refresh_field(
        "employee_photo"
    );


    frm.refresh_field(
        "photo_status"
    );


    update_photo_action_message(frm);
}
